import SwiftUI
import UIKit

/// Replica of `FloatingViewportModifier`'s overlay, reduced to the two things
/// issue #114 asks about: which orientation the scene reports, and how much
/// horizontal safe area there is to bleed into.
@main
struct ProbeApp: App {
    var body: some Scene {
        WindowGroup { ProbeView() }
    }
}

private struct Reading {
    var size: CGSize = .zero
    var insets: EdgeInsets = .init()
    var deprecated: UIInterfaceOrientation = .unknown
    var effective: UIInterfaceOrientation = .unknown
    var locked = false
    var resizing = false
    var sceneCount = 0
    var screen: CGSize = .zero
}

private func name(_ o: UIInterfaceOrientation) -> String {
    switch o {
    case .portrait: "portrait"
    case .portraitUpsideDown: "portraitUpsideDown"
    case .landscapeLeft: "landscapeLeft"
    case .landscapeRight: "landscapeRight"
    default: "unknown"
    }
}

/// The switch under test, copied verbatim from `dockBleed(in:)`.
private func bleed(_ o: UIInterfaceOrientation, _ insets: EdgeInsets) -> String {
    switch o {
    case .landscapeLeft: "leading \(Int(insets.leading))"
    case .landscapeRight: "trailing \(Int(insets.trailing))"
    default: "none"
    }
}

private struct ProbeView: View {
    @State private var reading = Reading()

    var body: some View {
        TabView {
            Color.black.tabItem { Label("One", systemImage: "1.circle") }
        }
        .overlay {
            GeometryReader { geometry in
                let r = read(geometry)
                ZStack(alignment: .topLeading) {
                    // Left: what the code does today. Right: the replacement.
                    hud(r)
                    // The docked tab, drawn twice: flush with the reader, and bled.
                    marker(r, bled: false)
                    marker(r, bled: true)
                }
                .onAppear { reading = r }
                .onChange(of: geometry.size) { reading = read(geometry) }
            }
        }
        .task { requestOrientationIfAsked() }
    }

    private func hud(_ r: Reading) -> some View {
        VStack(alignment: .leading, spacing: 2) {
            Text("size \(Int(r.size.width))×\(Int(r.size.height))  screen \(Int(r.screen.width))×\(Int(r.screen.height))")
            Text("insets t\(Int(r.insets.top)) b\(Int(r.insets.bottom)) l\(Int(r.insets.leading)) r\(Int(r.insets.trailing))")
            Text("scenes \(r.sceneCount)")
            Text("deprecated  \(name(r.deprecated))")
                .foregroundStyle(.yellow)
            Text("effective   \(name(r.effective))")
                .foregroundStyle(.green)
            Text("locked \(r.locked ? "Y" : "N")  resizing \(r.resizing ? "Y" : "N")")
            Text("bleed(dep) \(bleed(r.deprecated, r.insets))")
                .foregroundStyle(.yellow)
            Text("bleed(eff) \(bleed(r.effective, r.insets))")
                .foregroundStyle(.green)
        }
        .font(.system(size: 13, weight: .semibold, design: .monospaced))
        .foregroundStyle(.white)
        .padding(6)
        .background(.black.opacity(0.85))
        .padding(.top, 40)
    }

    /// A 44 pt tab at the vertical centre of the trailing edge, flush and bled.
    private func marker(_ r: Reading, bled: Bool) -> some View {
        let inset = r.effective == .landscapeRight ? r.insets.trailing : 0
        let x = r.size.width - 22 + (bled ? inset : 0)
        return RoundedRectangle(cornerRadius: 8)
            .fill(bled ? Color.green.opacity(0.8) : Color.red.opacity(0.8))
            .frame(width: 44, height: 44)
            .position(x: x, y: r.size.height / 2 + (bled ? 50 : -50))
    }

    private func read(_ geometry: GeometryProxy) -> Reading {
        var r = Reading()
        r.size = geometry.size
        r.insets = geometry.safeAreaInsets
        let scenes = UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }
        r.sceneCount = scenes.count
        if let scene = scenes.first {
            r.deprecated = scene.interfaceOrientation
            r.effective = scene.effectiveGeometry.interfaceOrientation
            r.locked = scene.effectiveGeometry.isInterfaceOrientationLocked
            r.resizing = scene.effectiveGeometry.isInteractivelyResizing
            r.screen = scene.screen.bounds.size
        }
        return r
    }

    /// `requestGeometryUpdate` is the very mechanism that makes orientation a
    /// preference rather than a contract, so the probe drives it the same way.
    private func requestOrientationIfAsked() {
        let args = ProcessInfo.processInfo.arguments
        let mask: UIInterfaceOrientationMask? = if args.contains("left") {
            .landscapeLeft
        } else if args.contains("right") {
            .landscapeRight
        } else if args.contains("portrait") {
            .portrait
        } else {
            nil
        }
        guard let mask,
              let scene = UIApplication.shared.connectedScenes.compactMap({ $0 as? UIWindowScene }).first
        else { return }
        scene.requestGeometryUpdate(.iOS(interfaceOrientations: mask))
    }
}
