private let levels = ["INFO", "WARN", "DEBUG", "ERROR"]

private struct EdgeView: View {
    private var style: ScrollEdgeEffectStyle? {
        let args = ProcessInfo.processInfo.arguments
        if args.contains("automatic") { return .automatic }
        if args.contains("hard") { return .hard }
        if args.contains("none") { return nil }
        return .soft
    }

