import CoreGraphics
import Foundation
import ImageIO

func load(_ path: String) -> (w: Int, h: Int, px: [UInt8])? {
    guard let src = CGImageSourceCreateWithURL(URL(fileURLWithPath: path) as CFURL, nil),
          let img = CGImageSourceCreateImageAtIndex(src, 0, nil) else { return nil }
    let w = img.width, h = img.height
    var buf = [UInt8](repeating: 0, count: w * h * 4)
    let cs = CGColorSpaceCreateDeviceRGB()
    guard let ctx = CGContext(data: &buf, width: w, height: h, bitsPerComponent: 8,
                              bytesPerRow: w * 4, space: cs,
                              bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
    else { return nil }
    ctx.draw(img, in: CGRect(x: 0, y: 0, width: w, height: h))
    return (w, h, buf)
}

let a = CommandLine.arguments
guard a.count >= 3, let x = load(a[1]), let y = load(a[2]), x.w == y.w, x.h == y.h else {
    print("usage: diff A.png B.png [threshold]; images must match"); exit(1)
}
let threshold = a.count > 3 ? Int(a[3])! : 3
var changed = 0
var minX = x.w, maxX = -1, minY = x.h, maxY = -1
var rowMax = [Int](repeating: 0, count: x.h)
var peak = 0
for row in 0 ..< x.h {
    for col in 0 ..< x.w {
        let i = (row * x.w + col) * 4
        let d = max(abs(Int(x.px[i]) - Int(y.px[i])),
                    max(abs(Int(x.px[i + 1]) - Int(y.px[i + 1])),
                        abs(Int(x.px[i + 2]) - Int(y.px[i + 2]))))
        rowMax[row] = max(rowMax[row], d)
        peak = max(peak, d)
        if d > threshold {
            changed += 1
            minX = min(minX, col); maxX = max(maxX, col)
            minY = min(minY, row); maxY = max(maxY, row)
        }
    }
}
let total = x.w * x.h
print("size \(x.w)x\(x.h)  changed \(changed) px (\(String(format: "%.3f", Double(changed) * 100 / Double(total)))%)  peak delta \(peak)")
if maxX >= 0 {
    print("bbox x \(minX)…\(maxX)  y \(minY)…\(maxY)  (\(maxX - minX + 1)×\(maxY - minY + 1) px)")
    // Rows are what matter for a scroll edge effect: it is a horizontal band.
    let bands = stride(from: 0, to: x.h, by: 60).map { s -> String in
        let e = min(s + 60, x.h)
        return "\(s)-\(e): \(rowMax[s ..< e].max() ?? 0)"
    }
    print("row-max by 60px band:")
    print(bands.prefix(12).joined(separator: "  "))
} else {
    print("byte-identical above threshold \(threshold)")
}
